10	func sample() *Ledger {
11		l := NewLedger()
12		_ = ApplyEntry(l, Entry{ID: "e1", Account: "cash", Amount: 10000, Category: "salary"})
13		_ = ApplyEntry(l, Entry{ID: "e2", Account: "cash", Amount: -2500, Category: "groceries"})
14		_ = ApplyEntry(l, Entry{ID: "e3", Account: "savings", Amount: 5000, Category: "transfer"})
15		return l
16	}
17	
18	func TestApplyEntryRejectsDuplicates(t *testing.T) {
19		l := sample()
20		if err := ApplyEntry(l, Entry{ID: "e1", Account: "cash", Amount: 1}); err != ErrDuplicate {
21			t.Fatalf("duplicate accepted: %v", err)
22		}
23	}
24	
25	func TestBalanceSumsAccount(t *testing.T) {
26		l := sample()
27		if got := l.Balance("cash"); got != 7500 {
28			t.Fatalf("cash balance = %d, want 7500", got)
29		}
30	}
31	
32	func TestTransferMovesAmount(t *testing.T) {
33		l := sample()
34		if err := Transfer(l, "t1", "cash", "savings", 500); err != nil {
35			t.Fatal(err)
36		}
37		if l.Balance("cash") != 7000 || l.Balance("savings") != 5500 {
38			t.Fatalf("balances after transfer: cash=%d savings=%d", l.Balance("cash"), l.Balance("savings"))
39		}
40	}
41	
42	func TestSaveLoadRoundTrip(t *testing.T) {
43		l := sample()
44		var buf bytes.Buffer
45		if err := Save(&buf, l); err != nil {
46			t.Fatal(err)
47		}
48		loaded, err := Load(strings.NewReader(buf.String()))
49		if err != nil {
50			t.Fatal(err)
51		}
52		if loaded.Balance("cash") != l.Balance("cash") {
53			t.Fatalf("round trip changed cash balance")
54		}
55	}
56	
57	func TestQuarterSummaryCountsEntries(t *testing.T) {
58		l := sample()
59		now := time.Now().UTC()
60		summary := SummarizeQuarter(l, now.Year(), (int(now.Month())-1)/3+1)
61		if summary.Entries != 3 {
62			t.Fatalf("entries in quarter = %d, want 3", summary.Entries)
63		}
64	}
65	
66	// TestFormatAmountNegative documents a known formatting gap: negative amounts
67	// below one major unit lose their sign. It fails on purpose so the V1 scenario
68	// has a real failure to report.
69	func TestFormatAmountNegative(t *testing.T) {
70		if got := FormatAmount(-5, "USD"); got != "-0.05 USD" {
71			t.Fatalf("FormatAmount(-5) = %q, want -0.05 USD", got)
72		}
73	}
74	
75	func TestBetweenUsesHalfOpenRange(t *testing.T) {
76		l := NewLedger()
77		day := time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
78		_ = ApplyEntry(l, Entry{ID: "a", Account: "x", Amount: 1, Posted: day})
79		_ = ApplyEntry(l, Entry{ID: "b", Account: "x", Amount: 1, Posted: day.Add(24 * time.Hour)})
80		if got := len(l.Between(day, day.Add(24*time.Hour))); got != 1 {
81			t.Fatalf("Between returned %d entries, want 1", got)
82		}
83	}
