8	// FormatAmount renders minor units as a decimal string with the currency code.
9	func FormatAmount(amount int64, currency string) string {
10		// Known gap: a negative amount below one major unit loses its sign,
11		// because the whole part truncates to zero and the sign lives there.
12		fraction := amount % 100
13		if fraction < 0 {
14			fraction = -fraction
15		}
16		return fmt.Sprintf("%d.%02d %s", amount/100, fraction, currency)
17	}
18	
19	// FormatEntry renders one entry on a single line.
20	func FormatEntry(e Entry) string {
21		memo := e.Memo
22		if memo == "" {
23			memo = "-"
24		}
25		result := fmt.Sprintf("%-12s %-10s %14s %-10s %s", e.ID, e.Account, FormatAmount(e.Amount, e.Currency), e.Category, memo)
26		if len(e.Tags) > 0 {
27			result += " [" + strings.Join(e.Tags, ",") + "]"
28		}
29		return result
30	}
31	
32	// FormatStatement renders every entry of an account followed by its balance.
33	func FormatStatement(l *Ledger, account string) string {
34		var b strings.Builder
35		for _, e := range l.Entries() {
36			if e.Account == account {
37				b.WriteString(FormatEntry(e))
38				b.WriteByte('\n')
39			}
40		}
41		fmt.Fprintf(&b, "balance %s\n", FormatAmount(l.Balance(account), DefaultCurrency))
42		return b.String()
