		reportSection16(l),
		reportSection17(l),
		reportSection18(l),
		reportSection19(l),
		reportSection20(l),
		reportSection21(l),
		reportSection22(l),
		reportSection23(l),
		reportSection24(l),
		reportSection25(l),
		reportSection26(l),
		reportSection27(l),
		reportSection28(l),
		reportSection29(l),
		reportSection30(l),
		reportSection31(l),
		reportSection32(l),
		reportSection33(l),
		reportSection34(l),
		reportSection35(l),
		reportSection36(l),
		reportSection37(l),
		reportSection38(l),
		reportSection39(l),
		reportSection40(l),
		reportSection41(l),
		reportSection42(l),
		reportSection43(l),
		reportSection44(l),
		reportSection45(l),
		reportSection46(l),
		reportSection47(l),
		reportSection48(l),
		reportSection49(l),
		reportSection50(l),
		reportSection51(l),
		reportSection52(l),
	}
	var b strings.Builder
	for _, s := range sections {
		b.WriteString(s.Title)
		b.WriteByte('\n')
		for _, line := range s.Lines {
			b.WriteString(line)
			b.WriteByte('\n')
		}
	}
	return b.String()
}

package ledger

import (
	"bytes"
	"strings"
	"testing"
	"time"
)

func sample() *Ledger {
	l := NewLedger()
	_ = ApplyEntry(l, Entry{ID: "e1", Account: "cash", Amount: 10000, Category: "salary"}, false)
	_ = ApplyEntry(l, Entry{ID: "e2", Account: "cash", Amount: -2500, Category: "groceries"}, false)
	_ = ApplyEntry(l, Entry{ID: "e3", Account: "savings", Amount: 5000, Category: "transfer"}, false)
	return l
}

func TestApplyEntryRejectsDuplicates(t *testing.T) {
	l := sample()
	if err := ApplyEntry(l, Entry{ID: "e1", Account: "cash", Amount: 1}); err != ErrDuplicate {
		t.Fatalf("duplicate accepted: %v", err)
	}
}

func TestBalanceSumsAccount(t *testing.T) {
	l := sample()
	if got := l.Balance("cash"); got != 7500 {
		t.Fatalf("cash balance = %d, want 7500", got)
	}
}

